package vm

import (
	"sort"
	"sync"
)

// The member data is generated by tools/genemoji into emoji_strings.go.

var rgiEmoji = sync.OnceValue(func() []string {
	seen := map[string]bool{}
	var all []string
	names := make([]string, 0, len(propertiesOfStrings))
	for name := range propertiesOfStrings {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		for _, s := range propertiesOfStrings[name] {
			if !seen[s] {
				seen[s] = true
				all = append(all, s)
			}
		}
	}
	return all
})

// PropertyOfStrings returns the members of the Unicode property of strings
// named name (ECMA-262 table "Binary Unicode properties of strings"), such as
// RGI_Emoji, and whether name is one. The name must match exactly: unlike
// character properties, these have no aliases. Only the v flag admits them.
//
// The returned slice is shared and must not be modified.
func PropertyOfStrings(name string) ([]string, bool) {
	if name == "RGI_Emoji" {
		return rgiEmoji(), true
	}
	members, ok := propertiesOfStrings[name]
	return members, ok
}

// PropertyOfStringsRunes is PropertyOfStrings with each member as code
// points. The result is built once per property and shared by every caller,
// so that naming a property of strings costs a pattern nothing (RGI_Emoji has
// nearly 4,000 members); it must not be modified.
func PropertyOfStringsRunes(name string) ([][]rune, bool) {
	if v, ok := propertyRunes.Load(name); ok {
		return v.([][]rune), true
	}
	members, ok := PropertyOfStrings(name)
	if !ok {
		return nil, false
	}
	strs := make([][]rune, len(members))
	for i, m := range members {
		strs[i] = []rune(m)
	}
	v, _ := propertyRunes.LoadOrStore(name, strs)
	return v.([][]rune), true
}

var propertyRunes sync.Map // name -> [][]rune; one entry per property of strings

// emojiProperty returns the membership test for an emoji binary property.
func emojiProperty(name string) func(rune) bool {
	ranges, ok := emojiProperties[name]
	if !ok {
		panic("vm: no emoji property " + name)
	}
	return func(r rune) bool { return inRanges(ranges, r) }
}
